import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
  Img, // Kept in import as per rules, but unused
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type GolfSplitScreenProps = Record<string, any>;

// Helper for ball animation logic
const getBallPosition = (
  cycle: number,
  t: number,
  startX: number,
  targetX: number,
  startY: number,
  s: number // animation scale passed in to adjust spatial deviations
) => {
  const impactFrame = 22;
  const rollEndFrame = 40;

  if (t < impactFrame) {
    return { x: startX, y: startY, scale: 1, opacity: 1 };
  }

  // Calculate base progress with deceleration
  const progress = interpolate(t, [impactFrame, rollEndFrame], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  const dist = targetX - startX;
  let x = startX + dist * progress;
  let y = startY;
  let scale = 1;
  let opacity = 1;

  // Define the 8 different outcomes
  switch (cycle) {
    case 0: // Underhit 1
      x = startX + dist * 0.6 * progress;
      break;
    case 1: // Overhit
      x = startX + dist * 1.15 * progress;
      break;
    case 2: // Miss Top
      y = startY - interpolate(progress, [0, 1], [0, 25 * s]);
      break;
    case 3: // Miss Bottom
      y = startY + interpolate(progress, [0, 1], [0, 25 * s]);
      break;
    case 4: // Lip out front (stops right at edge)
      x = startX + (dist - 15 * s) * progress;
      break;
    case 5: // Curve around hole
      if (progress > 0.8) {
        const curveProg = interpolate(progress, [0.8, 1], [0, Math.PI]);
        y = startY - Math.sin(curveProg) * 15 * s;
        x = startX + dist * 0.9 + Math.cos(curveProg) * 15 * s;
      }
      break;
    case 6: // Underhit 2
      x = startX + dist * 0.85 * progress;
      break;
    case 7: // Make!
    default:
      if (t >= 35) {
        // Drop in hole animation
        const dropProg = interpolate(t, [35, 40], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        scale = interpolate(dropProg, [0, 1], [1, 0]);
        opacity = interpolate(dropProg, [0, 1], [1, 0]);
        y = startY + dropProg * 5 * s;
        x = targetX; // Lock to center of hole
      } else {
        // Roll to center
        const rollProg = interpolate(t, [impactFrame, 35], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: Easing.out(Easing.quad),
        });
        x = startX + dist * rollProg;
      }
      break;
  }

  return { x, y, scale, opacity };
};

export const GolfSplitScreen: React.FC<GolfSplitScreenProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 15, // Schema duration remains but unused in this snippet directly
  accentColor = "#2a75ff",
  topText = "This is not failure",
  middleText = "This is",
  topTextSize = 42,
  middleTextSize = 36,
  topTextYOffset = 0,
  middleTextYOffset = 0,
  topAnimationYOffset = 0,
  bottomAnimationYOffset = 0,
  animationScale = 1,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout calculations
  const topSceneCenterY = (height * 0.3) + topAnimationYOffset;
  const bottomSceneCenterY = (height * 0.7) + bottomAnimationYOffset;
  const startX = width * 0.25;
  const targetX = width * 0.75;
  const s = animationScale; // Map prop to shorthand scale factor

  // Animation Timings
  const framesPerCycle = 50;
  const maxCycles = 7; // 0 to 7 = 8 swings
  const currentCycleUnclamped = Math.floor(frame / framesPerCycle);
  const cycle = Math.min(currentCycleUnclamped, maxCycles);
  
  // Local time within the current cycle. If we've finished all cycles, 
  // lock the time to the end of the last cycle to maintain the final pose.
  const t = currentCycleUnclamped > maxCycles 
    ? framesPerCycle 
    : frame % framesPerCycle;

  // SVG Glow Filter Definition
  const SVGDefs = (
    <defs>
      <filter id="neon-glow" x="-50%" y="-50%" width="200%" height="200%">
        <feGaussianBlur stdDeviation="8" result="coloredBlur" />
        <feMerge>
          <feMergeNode in="coloredBlur" />
          <feMergeNode in="coloredBlur" />
          <feMergeNode in="SourceGraphic" />
        </feMerge>
      </filter>
      
      <linearGradient id="reflection-fade" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor="rgba(255,255,255,0.4)" />
        <stop offset="60%" stopColor="rgba(255,255,255,0)" />
      </linearGradient>

      <mask id="fade-mask">
        <rect x="0" y="0" width={width} height={height} fill="url(#reflection-fade)" />
      </mask>
    </defs>
  );

  // Reusable Scene Renderer (used for both real scene and reflection)
  const renderSceneItems = (isTop: boolean) => {
    // Array to hold all visible balls
    let activeBalls: { x: number; y: number; scale: number; opacity: number; id: string }[] = [];
    
    if (isTop) {
      // Top scene: render all previously completed cycles plus the current one
      const endLimit = Math.min(currentCycleUnclamped, maxCycles);
      for (let c = 0; c <= endLimit; c++) {
        if (c < currentCycleUnclamped) {
          // Completed cycle: fetch final rested position
          activeBalls.push({ 
            ...getBallPosition(c, framesPerCycle, startX, targetX, 0, s), 
            id: `top-ball-${c}` 
          });
        } else {
          // Current active cycle: fetch current animated position
          activeBalls.push({ 
            ...getBallPosition(c, t, startX, targetX, 0, s), 
            id: `top-ball-${c}` 
          });
        }
      }
    } else {
      // Bottom scene: ball stays static
      activeBalls.push({ x: startX, y: 0, scale: 1, opacity: 1, id: 'bottom-ball' });
    }

    // Club Animation Paths
    // Top club swings back (left), hits the ball (angle -15), stops, then resets to 0 before cycle ends
    const topClubAngle = interpolate(
      t,
      [0, 15, 22, 40, 50],
      [0, 65, -15, -15, 0],
      { easing: Easing.bezier(0.25, 0.1, 0.25, 1), extrapolateRight: "clamp" }
    );

    // Bottom club swings back (left), stops before hitting the ball (angle 15), stays, then resets to 0
    const bottomClubAngle = interpolate(
      t,
      [0, 15, 20, 40, 50],
      [0, 65, 15, 15, 0],
      { easing: Easing.bezier(0.25, 0.1, 0.25, 1), extrapolateRight: "clamp" }
    );

    const clubAngle = isTop ? topClubAngle : bottomClubAngle;

    // Impact Effect Calculations (Top scene only)
    const impactProg = interpolate(t, [22, 30], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.quad),
    });
    const impactOpacity = interpolate(impactProg, [0, 1], [1, 0]);

    return (
      <g>
        {/* The Hole */}
        <ellipse cx={targetX} cy={0} rx={16 * s} ry={4 * s} fill="#000" stroke="#555" strokeWidth={1.5 * s} />
        
        {/* The Flag Pole */}
        <line x1={targetX + 5 * s} y1={0} x2={targetX + 5 * s} y2={-80 * s} stroke="#666" strokeWidth={2 * s} />
        
        {/* The Flag */}
        <path 
          d={`M ${targetX + 6 * s} ${-80 * s} Q ${targetX + 25 * s} ${-85 * s} ${targetX + 40 * s} ${-70 * s} Q ${targetX + 25 * s} ${-65 * s} ${targetX + 6 * s} ${-60 * s} Z`} 
          fill={accentColor} 
          filter="url(#neon-glow)" 
        />

        {/* Impact Visual Effect */}
        {isTop && t >= 22 && t <= 35 && (
          <g transform={`translate(${startX}, 0)`}>
            {/* Outer ripple */}
            <circle
              r={(5 + impactProg * 20) * s}
              fill="none"
              stroke={accentColor}
              strokeWidth={4 * impactOpacity * s}
              opacity={impactOpacity}
              filter="url(#neon-glow)"
            />
            {/* Inner intense flash */}
            <circle
              r={(5 + impactProg * 8) * s}
              fill="white"
              opacity={impactOpacity * 0.8}
              filter="url(#neon-glow)"
            />
            {/* Spark lines */}
            {[0, 45, 90, 135, 180, 225, 270, 315].map((angle, i) => {
              const rad = (angle * Math.PI) / 180;
              const d1 = (8 + impactProg * 5) * s;
              const d2 = (12 + impactProg * 20) * s;
              return (
                <line
                  key={i}
                  x1={Math.cos(rad) * d1}
                  y1={Math.sin(rad) * d1}
                  x2={Math.cos(rad) * d2}
                  y2={Math.sin(rad) * d2}
                  stroke={accentColor}
                  strokeWidth={2 * impactOpacity * s}
                  opacity={impactOpacity}
                />
              );
            })}
          </g>
        )}

        {/* The Golf Club */}
        <g transform={`translate(${startX - 20 * s}, ${-80 * s}) rotate(${clubAngle} 0 0)`}>
          <line x1={0} y1={0} x2={0} y2={80 * s} stroke="#888" strokeWidth={3 * s} />
          {/* Club Head */}
          <path d={`M ${-5 * s} ${75 * s} L ${15 * s} ${75 * s} Q ${18 * s} ${78 * s} ${15 * s} ${80 * s} L ${-10 * s} ${80 * s} Q ${-15 * s} ${75 * s} ${-5 * s} ${75 * s} Z`} fill="#ccc" />
        </g>

        {/* The Golf Ball(s) */}
        {activeBalls.map((ball) => (
          ball.opacity > 0 && (
            <circle
              key={ball.id}
              cx={ball.x}
              cy={ball.y}
              r={5 * ball.scale * s}
              fill={accentColor}
              filter="url(#neon-glow)"
              opacity={ball.opacity}
            />
          )
        ))}
      </g>
    );
  };

  const TopTextGlow = useMemo(() => {
    const parts = topText.split(/(not failure)/i);
    return parts.map((part, i) => {
      if (part.toLowerCase() === "not failure") {
        return (
          <span key={i} style={{ color: accentColor, textShadow: `0 0 15px ${accentColor}` }}>
            {part}
          </span>
        );
      }
      return <span key={i} style={{ color: "#666" }}>{part}</span>;
    });
  }, [topText, accentColor]);


  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter, sans-serif" }}>
      
      {/* SVG Canvas for all graphical elements */}
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0 }}>
        {SVGDefs}
        
        {/* --- TOP SCENE --- */}
        <g transform={`translate(0, ${topSceneCenterY})`}>
          {renderSceneItems(true)}
        </g>
        
        {/* Top Scene Reflection */}
        <g 
          transform={`translate(0, ${topSceneCenterY}) scale(1, -1)`} 
          mask="url(#fade-mask)"
        >
           {renderSceneItems(true)}
        </g>

        {/* --- BOTTOM SCENE --- */}
        <g transform={`translate(0, ${bottomSceneCenterY})`}>
          {renderSceneItems(false)}
        </g>

        {/* Bottom Scene Reflection */}
        <g 
          transform={`translate(0, ${bottomSceneCenterY}) scale(1, -1)`} 
          mask="url(#fade-mask)"
        >
           {renderSceneItems(false)}
        </g>
      </svg>

      {/* --- TEXT OVERLAYS --- */}
      
      {/* Top Text */}
      <div style={{
        position: "absolute",
        top: topSceneCenterY - (80 * animationScale) - topTextSize + topTextYOffset,
        width: "100%",
        textAlign: "center",
        fontSize: `${topTextSize}px`,
        fontWeight: 600,
        letterSpacing: "-0.02em",
        zIndex: 10
      }}>
        {TopTextGlow}
      </div>

      {/* Middle Text */}
      <div style={{
        position: "absolute",
        top: height * 0.5 - (middleTextSize / 2) + middleTextYOffset,
        width: "100%",
        textAlign: "center",
        fontSize: `${middleTextSize}px`,
        color: "#aaa",
        fontWeight: 500,
        zIndex: 10
      }}>
        {middleText}
      </div>

    </AbsoluteFill>
  );
};

export default GolfSplitScreen;